9→const sha = (value) => createHash('sha256').update(value).digest('hex');
10→const typed = (message, code, fields = {}) => Object.assign(new Error(message), { code, ...fields });
11→const abort = (ctx) => { if (ctx?.signal?.aborted) throw typed('behavior observation cancelled', 'cancelled'); };
12→const stable = (value) => {
13→  if (Array.isArray(value)) return `[${value.map(stable).join(',')}]`;
14→  if (value && typeof value === 'object') return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stable(value[key])}`).join(',')}}`;
15→  return JSON.stringify(value);
16→};
17→const RUNNER = String.raw`
18→const [targetUrl, exportName, encoded] = process.argv.slice(1);
19→const emit = process.stdout.write.bind(process.stdout);
20→const hardExit = process.exit.bind(process);
21→const removeAllListeners = process.removeAllListeners.bind(process);
22→const parse = JSON.parse.bind(JSON);
23→const arrayIsArray = Array.isArray.bind(Array);
24→const arrayPush = Function.call.bind(Array.prototype.push);
25→const objectCreate = Object.create.bind(Object);
26→const objectIs = Object.is.bind(Object);
27→const numberIsNaN = Number.isNaN.bind(Number);
28→const stringValue = String;
29→const bufferToString = Function.call.bind(Buffer.prototype.toString);
30→const { serialize } = await import('node:v8');
31→let nonce = ''; for await (const chunk of process.stdin) nonce += chunk;
32→const corpus = parse(Buffer.from(encoded, 'base64').toString('utf8'));
33→const finish = (payload) => {
34→  const frame = bufferToString(serialize({ nonce, nodeVersion: process.version, ...payload }), 'base64');
35→  removeAllListeners('beforeExit'); removeAllListeners('exit');
36→  emit('\nBATON_BEHAVIOR_RESULT:' + frame + '\n'); hardExit(0);
37→};
38→let fn;
39→try {
40→  const module = await import(targetUrl); fn = module[exportName];
41→  if (typeof fn !== 'function') throw Object.assign(new Error('named export is not a function'), { code: 'EXPORT_NOT_FUNCTION' });
42→} catch (error) {
43→  finish({ error: { name: stringValue(error?.name ?? 'Error'), message: stringValue(error?.message ?? error), code: error?.code ?? null } });
44→}
45→const observations = [];
46→for (let caseIndex = 0; caseIndex < corpus.length; caseIndex += 1) {
47→  try {
48→    const value = await fn(corpus[caseIndex]);
49→    const item = objectCreate(null); item.caseIndex = caseIndex; item.kind = 'return'; item.valueBytes = bufferToString(serialize(value), 'base64');
50→    if (value === undefined) item.valueType = 'undefined';
51→    else if (typeof value === 'number' && numberIsNaN(value)) { item.valueType = 'number'; item.numberClass = 'NaN'; }
52→    else if (typeof value === 'number' && objectIs(value, -0)) { item.valueType = 'number'; item.numberClass = '-0'; }
53→    else if (value === Infinity || value === -Infinity) { item.valueType = 'number'; item.numberClass = stringValue(value); }
54→    else if (value === null || typeof value === 'string' || typeof value === 'boolean' || typeof value === 'number') item.value = value;
55→    else if (typeof value === 'bigint') { item.valueType = 'bigint'; item.value = stringValue(value); }
56→    else item.valueType = arrayIsArray(value) ? 'array' : typeof value;
57→    arrayPush(observations, item);
58→  } catch (error) {
59→    const item = objectCreate(null); item.caseIndex = caseIndex; item.kind = 'throw'; item.name = stringValue(error?.name ?? 'Error'); item.message = stringValue(error?.message ?? error); item.code = error?.code ?? error?.cause?.code ?? null;
60→    arrayPush(observations, item);
61→  }
62→}
63→finish({ observations });
64→`;
