66→function executeNode(nodePath, args, { timeoutMs, maxOutputBytes, signal, env, input }) {
67→  return new Promise((resolve, reject) => {
68→    let settled = false; let stdout = ''; let stderr = ''; let failure = null;
69→    const child = spawn(nodePath, args, { stdio: ['pipe', 'pipe', 'pipe'], env });
70→    const finish = (error, value) => {
71→      if (settled) return; settled = true; clearTimeout(timer); signal?.removeEventListener('abort', onAbort);
72→      if (error) reject(error); else resolve(value);
73→    };
74→    const stop = (error) => { failure ??= error; try { child.kill('SIGKILL'); } catch { /* already gone */ } };
75→    const append = (which, chunk) => {
76→      if (which === 'stdout') stdout += chunk; else stderr += chunk;
77→      if (Buffer.byteLength(stdout) + Buffer.byteLength(stderr) > maxOutputBytes) stop(typed('behavior child output exceeds deployment budget', 'output_too_large'));
78→    };
79→    child.stdout.setEncoding('utf8'); child.stderr.setEncoding('utf8');
80→    child.stdout.on('data', (chunk) => append('stdout', chunk)); child.stderr.on('data', (chunk) => append('stderr', chunk));
81→    child.on('error', (error) => finish(typed(`behavior child spawn failed: ${error.message}`, 'execution_failed')));
82→    child.on('close', (code, childSignal) => {
83→      if (failure) { finish(failure); return; }
84→      if (code !== 0) { finish(typed(`behavior child exited ${code}${childSignal ? ` (${childSignal})` : ''}: ${stderr.slice(-1000)}`, 'execution_failed')); return; }
85→      finish(null, stdout);
86→    });
87→    const timer = setTimeout(() => stop(typed('behavior observation exceeded execution deadline', 'execution_timeout')), timeoutMs);
88→    const onAbort = () => stop(typed('behavior observation cancelled', 'cancelled'));
89→    if (signal?.aborted) onAbort(); else signal?.addEventListener('abort', onAbort, { once: true });
90→    child.stdin.on('error', () => {}); child.stdin.end(input);
91→  });
92→}
