103→function validatePath(path) {
104→  if (typeof path !== 'string' || path.length === 0 || isAbsolute(path) || path.split(/[\\/]+/).includes('..')) throw typed('behavior target path escapes root', 'path_escape');
105→  if (!['.js', '.mjs'].includes(extname(path).toLowerCase())) throw typed('behavior fingerprint supports dependency-free JavaScript ESM only', 'unsupported_language');
106→  return path;
107→}
108→
109→function target(root, path, maxSourceBytes) {
110→  if (typeof root !== 'string' || root.length === 0) throw new TypeError('behavior root required');
111→  const realRoot = realpathSync(root); let realTarget;
112→  try { realTarget = realpathSync(resolve(realRoot, validatePath(path))); }
113→  catch (error) { if (error?.code === 'path_escape' || error?.code === 'unsupported_language') throw error; throw typed('behavior target unavailable', 'target_unavailable'); }
114→  const rel = relative(realRoot, realTarget);
115→  if (rel === '' || rel === '..' || rel.startsWith(`..${process.platform === 'win32' ? '\\' : '/'}`) || isAbsolute(rel)) throw typed('behavior target escapes root', 'path_escape');
116→  if (!statSync(realTarget).isFile()) throw typed('behavior target must be a file', 'target_unavailable');
117→  const source = readFileSync(realTarget); if (source.byteLength > maxSourceBytes) throw typed('behavior source exceeds deployment budget', 'source_too_large');
118→  return { realTarget, source, sourceDigest: sha(source) };
119→}
120→
121→function corpusBytes(corpus, maxCorpusCases, maxInputBytes) {
122→  if (!Array.isArray(corpus)) throw new TypeError('behavior corpus must be an array');
123→  if (corpus.length === 0 || corpus.length > maxCorpusCases) throw typed('behavior corpus exceeds deployment case budget', 'corpus_too_large');
124→  const json = (value, seen = new Set()) => {
125→    if (value === null || typeof value === 'string' || typeof value === 'boolean') return;
126→    if (typeof value === 'number') { if (!Number.isFinite(value)) throw typed('behavior corpus must contain finite JSON numbers', 'invalid_corpus'); return; }
127→    if (typeof value !== 'object' || seen.has(value)) throw typed('behavior corpus must contain only acyclic JSON values', 'invalid_corpus');
128→    seen.add(value);
129→    if (Array.isArray(value)) for (const item of value) json(item, seen);
130→    else {
131→      const proto = Object.getPrototypeOf(value); if (proto !== Object.prototype && proto !== null) throw typed('behavior corpus objects must be plain JSON objects', 'invalid_corpus');
132→      for (const item of Object.values(value)) json(item, seen);
133→    }
134→    seen.delete(value);
135→  };
136→  json(corpus);
137→  let serialized;
138→  try { serialized = JSON.stringify(corpus); } catch { throw typed('behavior corpus must be JSON serializable', 'invalid_corpus'); }
139→  if (serialized === undefined || Buffer.byteLength(serialized) > maxInputBytes) throw typed('behavior corpus exceeds deployment byte budget', 'corpus_too_large');
140→  return { serialized, digest: sha(serialized) };
141→}
