143→export class AtlasBehaviorFingerprint {
144→  constructor(opts = {}) {
145→    if (!opts.artifactRoot) throw new TypeError('behavior artifactRoot required');
146→    for (const key of ['maxSourceBytes', 'maxCorpusCases', 'maxInputBytes', 'maxOutputBytes', 'maxArtifactBytes', 'timeoutMs']) {
147→      if (!Number.isSafeInteger(opts[key]) || opts[key] <= 0) throw new TypeError(`${key} must be deployment-derived`);
148→    }
149→    this.artifactRoot = opts.artifactRoot;
150→    this.maxSourceBytes = opts.maxSourceBytes;
151→    this.maxCorpusCases = opts.maxCorpusCases;
152→    this.maxInputBytes = opts.maxInputBytes;
153→    this.maxOutputBytes = opts.maxOutputBytes;
154→    this.maxArtifactBytes = opts.maxArtifactBytes;
155→    this.timeoutMs = opts.timeoutMs;
156→    this.nodePath = opts.nodePath ?? process.execPath;
157→    this.now = opts.now ?? Date.now;
158→    this.record = opts.record ?? null;
159→    mkdirSync(this.artifactRoot, { recursive: true, mode: 0o700 });
160→  }
161→
162→  card() {
163→    return Object.freeze({
164→      name: 'atlas-behavior-fingerprint', version: '0.1.0', underlying: [`node-permission-model@${process.version}`],
165→      ops: {
166→        'behavior.fingerprint': { deterministic: true, latency_class: 'bounded_batch', side_effects: 'executes_target_in_throwaway_permission_sandbox', reverifiable: true },
167→        'behavior.compare': { deterministic: true, latency_class: 'bounded_batch', side_effects: 'executes_targets_in_throwaway_permission_sandboxes', reverifiable: true },
168→      },
169→      limitations: ['dependency-free JavaScript ESM named exports only', 'pinned-corpus observation is not semantic equivalence', 'no input generation or coverage claim', 'filesystem writes, network, child processes, and workers denied'],
170→    });
171→  }
172→
173→  async _once(source, exportName, corpus, ctx) {
174→    abort(ctx);
175→    // macOS exposes its temp root through /var -> /private/var. Node's permission resolver uses
176→    // canonical paths, so grant the canonical sandbox rather than the lexical symlink path.
177→    const sandbox = realpathSync(mkdtempSync(join(tmpdir(), 'baton-behavior-sandbox-')));
178→    const targetPath = join(sandbox, 'target.mjs'); writeFileSync(targetPath, source, { mode: 0o400 });
179→    try {
180→      const encoded = Buffer.from(corpus).toString('base64');
181→      const nonce = randomBytes(32).toString('hex');
182→      const stdout = await executeNode(this.nodePath, [
183→        '--permission', `--allow-fs-read=${sandbox}`, '--input-type=module', '-e', RUNNER,
184→        pathToFileURL(targetPath).href, exportName, encoded,
185→      ], {
186→        timeoutMs: this.timeoutMs, maxOutputBytes: this.maxOutputBytes, signal: ctx?.signal, input: nonce,
187→        env: { LANG: 'C', LC_ALL: 'C', TZ: 'UTC', NODE_NO_WARNINGS: '1' },
188→      });
189→      const frames = stdout.split('\n').filter((line) => line.startsWith('BATON_BEHAVIOR_RESULT:'));
190→      if (frames.length !== 1) throw typed('behavior child produced an ambiguous result channel', 'observation_protocol');
191→      let envelope;
192→      try { envelope = deserialize(Buffer.from(frames[0].slice('BATON_BEHAVIOR_RESULT:'.length), 'base64')); }
193→      catch { throw typed('behavior child result frame is invalid', 'observation_protocol'); }
194→      if (!envelope || envelope.nonce !== nonce || typeof envelope.nodeVersion !== 'string') throw typed('behavior child result frame failed runner authentication', 'observation_protocol');
195→      if (envelope.error) throw typed(`behavior runner failed: ${envelope.error.message}`, envelope.error.code === 'EXPORT_NOT_FUNCTION' ? 'invalid_export' : 'execution_failed');
196→      if (!Array.isArray(envelope.observations)) throw typed('behavior child result frame has invalid schema', 'observation_protocol');
197→      const observations = envelope.observations;
198→      if (Buffer.byteLength(JSON.stringify(observations)) > this.maxOutputBytes) throw typed('behavior observations exceed deployment budget', 'output_too_large');
199→      if (observations.some((item) => item.kind === 'throw' && item.code === 'ERR_ACCESS_DENIED')) throw typed('target attempted an operation denied by the permission sandbox', 'sandbox_violation');
200→      return { observations, nodeVersion: envelope.nodeVersion };
201→    } catch (error) {
202→      if (['sandbox_violation', 'output_too_large', 'execution_failed', 'observation_protocol', 'invalid_export', 'execution_timeout', 'cancelled'].includes(error?.code)) throw error;
203→      if (error?.name === 'AbortError' || error?.code === 'ABORT_ERR') throw typed('behavior observation cancelled', 'cancelled');
204→      throw typed(`behavior child failed: ${error?.message ?? error}`, error?.message?.includes('EXPORT_NOT_FUNCTION') ? 'invalid_export' : 'execution_failed');
205→    } finally {
206→      rmSync(sandbox, { recursive: true, force: true });
207→    }
208→  }
209→
210→  async _observe(root, path, exportName, corpus, ctx) {
211→    if (typeof exportName !== 'string' || !/^[A-Za-z_$][\w$]*$/.test(exportName)) throw typed('valid named export required', 'invalid_export');
212→    const resolved = target(root, path, this.maxSourceBytes); const input = corpusBytes(corpus, this.maxCorpusCases, this.maxInputBytes);
213→    const first = await this._once(resolved.source, exportName, input.serialized, ctx); abort(ctx);
214→    const second = await this._once(resolved.source, exportName, input.serialized, ctx);
215→    if (first.nodeVersion !== second.nodeVersion || stable(first.observations) !== stable(second.observations)) throw typed('target observations differ across isolated repetitions', 'nondeterministic');
216→    return {
217→      path, exportName, sourceDigest: resolved.sourceDigest, corpusDigest: input.digest, observations: first.observations,
218→      nodeVersion: first.nodeVersion,
219→      sandbox: { permissionModel: true, fsRead: 'isolated_target_only', fsWrite: 'denied', network: 'denied', childProcess: 'denied', workers: 'denied' },
220→    };
221→  }
222→
223→  _writeResult(op, artifact, items, ctx, started) {
224→    const serialized = `${JSON.stringify(artifact)}\n`; const digest = sha(serialized);
225→    if (Buffer.byteLength(serialized) > this.maxArtifactBytes) throw typed('behavior artifact exceeds deployment budget', 'artifact_too_large');
226→    const path = join(this.artifactRoot, `${digest}.json`);
227→    if (existsSync(path) && sha(readFileSync(path)) !== digest) throw typed('behavior artifact integrity failure', 'artifact_integrity');
228→    if (!existsSync(path)) writeFileSync(path, serialized, { mode: 0o600, flag: 'wx' });
229→    const payload = bounded(items, ctx.budgetTokens); const truncated = payload.length < items.length;
230→    const kind = op === 'behavior.fingerprint' ? 'behavior_fingerprint' : 'behavior_comparison';
231→    const meaning = op === 'behavior.fingerprint' ? 'observed_pinned_corpus_not_semantic_equivalence' : 'observed_corpus_agreement_not_semantic_equivalence';
232→    const result = Object.freeze({
233→      op, status: truncated ? 'needs_resume' : 'ok', summary: op === 'behavior.fingerprint' ? `observed ${artifact.observations.length} pinned cases` : `${artifact.divergences.length} observed divergences`, payload,
234→      refs: [{ handle: `art:sha256:${digest}`, kind, digest, bytes: Buffer.byteLength(serialized), mediaType: `application/vnd.baton.atlas-${kind.replaceAll('_', '-')}+json`, path }],
235→      ...(truncated ? { cursor: `atlas-behavior:${digest}:${payload.length}` } : {}),
236→      cost: { tokens_out: Math.ceil(Buffer.byteLength(JSON.stringify(payload)) / 4), wall_ms: Math.max(0, this.now() - started), usd: 0, underlying: `node-permission-model@${artifact.nodeVersion}` },
237→      provenance: { artifactDigest: digest, sourceDigests: artifact.sourceDigests ?? [artifact.sourceDigest], corpusDigest: artifact.corpusDigest, exportName: artifact.exportName, nodeVersion: artifact.nodeVersion, sandbox: artifact.sandbox, deterministic: true, meaning },
238→    });
239→    this.record?.({ kind: 'capability.op.completed', actor: ctx.actor ?? 'orchestrator', op, digest, status: result.status });
240→    return result;
241→  }
242→
243→  async invoke(op, args, ctx) {
244→    if (!ctx || !Number.isSafeInteger(ctx.budgetTokens) || ctx.budgetTokens <= 0) throw new TypeError('positive budgetTokens required');
245→    if (!['behavior.fingerprint', 'behavior.compare'].includes(op)) throw typed(`unsupported behavior operation: ${op}`, 'unsupported_op');
246→    abort(ctx); const started = this.now(); this.record?.({ kind: 'capability.op.started', actor: ctx.actor ?? 'orchestrator', op });
247→    if (op === 'behavior.fingerprint') {
248→      const observed = await this._observe(ctx.root, validatePath(args?.path), args?.exportName, args?.corpus, ctx);
249→      const artifact = { schemaVersion: 1, op, ...observed };
250→      return this._writeResult(op, artifact, observed.observations, ctx, started);
251→    }
252→    const before = await this._observe(ctx.beforeRoot, validatePath(args?.beforePath), args?.exportName, args?.corpus, ctx); abort(ctx);
253→    const after = await this._observe(ctx.afterRoot, validatePath(args?.afterPath), args?.exportName, args?.corpus, ctx);
254→    const divergences = [];
255→    for (let caseIndex = 0; caseIndex < before.observations.length; caseIndex += 1) {
256→      if (stable(before.observations[caseIndex]) !== stable(after.observations[caseIndex])) divergences.push({ caseIndex, before: before.observations[caseIndex], after: after.observations[caseIndex] });
257→    }
258→    const comparison = { recordType: 'behavior_comparison', agree: divergences.length === 0, cases: before.observations.length, divergences };
259→    const artifact = {
260→      schemaVersion: 1, op, exportName: args.exportName, corpusDigest: before.corpusDigest,
261→      sourceDigests: [before.sourceDigest, after.sourceDigest], before: { path: before.path, observations: before.observations }, after: { path: after.path, observations: after.observations },
262→      nodeVersion: before.nodeVersion, sandbox: before.sandbox, divergences,
263→    };
264→    return this._writeResult(op, artifact, [comparison], ctx, started);
265→  }
266→
267→  async resume(ref, cursor, ctx) {
268→    if (!ctx || !Number.isSafeInteger(ctx.budgetTokens) || ctx.budgetTokens <= 0) throw new TypeError('positive budgetTokens required'); abort(ctx);
269→    const match = /^atlas-behavior:([a-f0-9]{64}):(\d+)$/.exec(cursor ?? ''); if (!match || match[1] !== ref?.digest) throw typed('invalid behavior cursor', 'invalid_cursor');
270→    let path; try { path = realpathSync(ref.path); } catch { throw typed('behavior artifact unavailable', 'artifact_integrity'); }
271→    const root = realpathSync(this.artifactRoot); if (path !== join(root, `${ref.digest}.json`)) throw typed('behavior artifact path escape', 'artifact_integrity');
272→    const bytes = readFileSync(path); if (sha(bytes) !== ref.digest) throw typed('behavior artifact digest mismatch', 'artifact_integrity');
273→    let artifact; try { artifact = JSON.parse(bytes); } catch { throw typed('behavior artifact JSON invalid', 'artifact_integrity'); }
274→    if (artifact.schemaVersion !== 1 || !['behavior.fingerprint', 'behavior.compare'].includes(artifact.op)) throw typed('behavior artifact schema mismatch', 'artifact_integrity');
275→    const items = artifact.op === 'behavior.fingerprint' ? artifact.observations : [{ recordType: 'behavior_comparison', agree: artifact.divergences.length === 0, cases: artifact.before.observations.length, divergences: artifact.divergences }];
276→    const offset = Number(match[2]); if (!Number.isSafeInteger(offset) || offset < 0 || offset > items.length) throw typed('invalid behavior cursor offset', 'invalid_cursor');
277→    const payload = bounded(items.slice(offset), ctx.budgetTokens); const next = offset + payload.length; const truncated = next < items.length;
278→    return Object.freeze({ op: artifact.op, status: truncated ? 'needs_resume' : 'ok', summary: `resumed ${payload.length} behavior records`, payload, refs: [ref], ...(truncated ? { cursor: `atlas-behavior:${ref.digest}:${next}` } : {}), cost: { tokens_out: Math.ceil(Buffer.byteLength(JSON.stringify(payload)) / 4), wall_ms: 0, usd: 0, underlying: `node-permission-model@${process.version}` }, provenance: { artifactDigest: ref.digest, resumed_from: offset, deterministic: true } });
279→  }
280→
281→  async reverify(claim, args, ctx) {
282→    const rerun = await this.invoke(claim?.op, args, ctx);
283→    return Object.freeze({ ok: rerun.refs[0].digest === claim?.refs?.[0]?.digest, observedDigest: rerun.refs[0].digest });
284→  }
285→}
